#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef vector<int> vi;

const char nl = '\n';
const ll INF = 0x3f3f3f3f;
const ll INFLL = 0x3f3f3f3f3f3f3f3f;
const ll MOD = 1e9+7;
const ld EPS = 1e-10;

const int T = 99;
const int C = 12;

struct Edge {
    int v, rev;
    ll flow, cap, cost;
};

vector<vector<Edge>> adj;
vector<bool> visited;
vector<int> parent;
vector<ll> potential, distance;

void init_graph(int n) {
    adj.assign(n, vector<Edge>());
    visited.assign(n, false);
    parent.assign(n, 0);
    potential.assign(n, 0);
    distance.assign(n, INF);
}

void add_edge(int a, int b, ll capacity, ll cost) {
    adj[a].push_back({b, (int)adj[b].size(), 0, capacity, cost});
    adj[b].push_back({a, (int)adj[a].size()-1, 0, 0, -cost});
}

ll min_cost_flow(int source, int sink, ll& total_cost, int n, bool sparse, ll lower_bound) {
    fill(visited.begin(), visited.end(), false);
    fill(distance.begin(), distance.end(), INF);
    distance[source] = 0;

    if (sparse) {
        priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
        pq.push({0, source});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (visited[u]) continue;
            visited[u] = true;
            for (const Edge& e : adj[u]) {
                if (e.flow <= e.cap - lower_bound && distance[e.v] > distance[u] + potential[u] - potential[e.v] + e.cost) {
                    distance[e.v] = distance[u] + potential[u] - potential[e.v] + e.cost;
                    parent[e.v] = e.rev;
                    pq.push({distance[e.v], e.v});
                }
            }
        }
    } else {
        for (int iter = 0; iter < n; iter++) {
            int u = -1;
            ll best = INF;
            for (int i = 0; i < n; i++) {
                if (!visited[i] && distance[i] < best) {
                    best = distance[i];
                    u = i;
                }
            }
            if (u == -1) break;
            visited[u] = true;
            for (const Edge& e : adj[u]) {
                if (e.flow <= e.cap - lower_bound && distance[e.v] > distance[u] + potential[u] - potential[e.v] + e.cost) {
                    distance[e.v] = distance[u] + potential[u] - potential[e.v] + e.cost;
                    parent[e.v] = e.rev;
                }
            }
        }
    }

    if (distance[sink] >= INF) return 0;

    ll df = INF;
    for (int u = sink; u != source; ) {
        const Edge& e = adj[u][parent[u]];
        df = min(df, adj[e.v][e.rev].cap - adj[e.v][e.rev].flow);
        u = e.v;
    }

    for (int u = sink; u != source; ) {
        Edge& e = adj[u][parent[u]];
        Edge& rev = adj[e.v][e.rev];
        rev.flow += df;
        e.flow -= df;
        total_cost += df * rev.cost;
        u = e.v;
    }

    for (int i = 0; i < n; i++) {
        if (distance[i] < INF)
            potential[i] += distance[i];
    }
    return df;
}

ll min_cost_flow_full(int source, int sink, ll& total_cost, int n) {
    fill(potential.begin(), potential.end(), 0);
    ll total_flow = 0;
    total_cost = 0;

    for (ll lb = 1LL << 30; lb > 0; lb >>= 1) {
        while (true) {
            ll df = min_cost_flow(source, sink, total_cost, n, true, lb);
            if (df == 0) break;
            total_flow += df;
        }
    }
    return total_flow;
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int source = 0;
    const int sink = n * T + 1;
    int graph_size = sink + 1;

    init_graph(graph_size);

    for (int i = 0; i < k; i++) {
        int a;
        cin >> a;
        add_edge(source, a, 1, 0);
    }

    for (int t = 0; t < T; t++) {
        add_edge(1 + t * n, sink, INF, 0);
        if (t > 0) {
            for (int i = 1; i <= n; i++) {
                add_edge(i + (t - 1) * n, i + t * n, INF, c);
            }
        }
    }

    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < C; j++) {
            int cost = (j + 1) * (j + 1) - j * j;
            for (int t = 1; t < T; t++) {
                add_edge(a + (t - 1) * n, b + t * n, 1, cost * d + c);
                add_edge(b + (t - 1) * n, a + t * n, 1, cost * d + c);
            }
        }
    }

    ll price, flow = min_cost_flow_full(source, sink, price, graph_size);
    assert(flow == k);
    cout << price << nl;

    return 0;
}
